254: export function useCreateMultiplixDispatch() {
255:   // A chave de idempotencia tem de sobreviver ao duplo clique: a RPC e
256:   // idempotente por client_request_id, nao por conteudo — duas chaves geram dois
257:   // disparos. Fica viva enquanto a tentativa esta em voo e e liberada no fim.
258:   const clientRequestIdRef = useRef<string | null>(null);
259:   return useMutation({
260:     mutationFn: async (input: CreateMultiplixDispatchInput): Promise<CreateMultiplixDispatchResult> => {
261:       if (!clientRequestIdRef.current) clientRequestIdRef.current = crypto.randomUUID();
262:       const clientRequestId = clientRequestIdRef.current;
263:       // F08: a criacao vive no servidor. A edge multiplix-audience re-resolve o
264:       // publico no Singu com o escopo do JWT e chama a RPC transacional
265:       // multiplix_create_draft (dispatch + destinatarios numa transacao,
266:       // idempotente por client_request_id). O navegador nao decide mais quem
267:       // recebe nem escreve direto em multiplix_dispatches/multiplix_recipients.
268:       const draft = await createMultiplixDraft({
269:         name: input.name,
270:         message_template: input.messageTemplate,
271:         company_ids: input.companyIds,
272:         contact_ids: input.contactIds ?? [],
273:         client_request_id: clientRequestId,
274:         scheduled_at: input.scheduledAt ?? null,
275:         confirm_over_limit: input.confirmOverLimit ?? false,
276:       });
277:       if (!draft.dispatch_id) throw new Error('Disparo criado sem identificador');
278:       const dispatchId = draft.dispatch_id;
279: 
280:       if (input.startNow) {
281:         // Nao aguarda: multiplix-send processa o loop de envio inteiro dentro
282:         // da mesma invocacao (sleep real de digitacao/intervalo por
283:         // destinatario), entao esperar aqui travaria o composer pelo tempo
284:         // total do disparo, sem permitir pausar/cancelar/acompanhar. Dispara
285:         // em background e deixa o monitor (que abre logo em seguida) refletir
286:         // o progresso via realtime/polling; se a janela de envio recusar o
287:         // start, o dispatch fica em 'draft' e o botao "Iniciar" do monitor
288:         // permite tentar de novo (com o erro real, via toast do runAction).
289:         invokeMultiplixSend(dispatchId, 'start').catch((startError) => {
290:           // Nao e so o caso esperado (fora da janela): auth/409/500/rede
291:           // tambem caem aqui, e sem avisar o usuario o disparo fica parado
292:           // (draft) ou preso em 'sending' sem ninguem saber o motivo.
293:           const message = startError instanceof Error ? startError.message : 'Erro ao iniciar disparo';
294:           console.error('multiplix-send start (background) falhou:', startError);
295:           toast.error(`Disparo salvo, mas o início falhou: ${message}`);
296:         });
297:       }
298: 
299:       return { id: dispatchId, recipientCount: draft.recipient_count, created: draft.created };
300:     },
301:     // Libera a chave so DEPOIS que a criacao terminou: duas chamadas simultaneas
302:     // (duplo clique) compartilham a chave e viram UM disparo; um novo disparo
303:     // depois disso recebe chave nova.
304:     onSettled: () => { clientRequestIdRef.current = null; },
305:   });

