34: CREATE OR REPLACE FUNCTION public.transition_multiplix_dispatch(p_dispatch_id uuid, p_action text, p_pause_reason text DEFAULT NULL::text)
35:  RETURNS TABLE(dispatch_id uuid, previous_status text, current_status text)
36:  LANGUAGE plpgsql
37:  SECURITY DEFINER
38:  SET search_path TO 'public', 'pg_temp'
39: AS $function$
40: DECLARE
41:   v_dispatch public.multiplix_dispatches%ROWTYPE;
42:   v_next_status text;
43:   v_closed integer := 0;
44: BEGIN
45:   IF COALESCE(auth.role(), '') <> 'service_role' THEN
46:     RAISE EXCEPTION 'service_role_required' USING ERRCODE = '42501';
47:   END IF;
48:   IF p_dispatch_id IS NULL OR p_action NOT IN ('start', 'pause', 'cancel') THEN
49:     RAISE EXCEPTION 'invalid_multiplix_dispatch_transition' USING ERRCODE = '22023';
50:   END IF;
51: 
52:   SELECT * INTO v_dispatch
53:   FROM public.multiplix_dispatches AS dispatch
54:   WHERE dispatch.id = p_dispatch_id
55:   FOR UPDATE;
56: 
57:   IF NOT FOUND THEN
58:     RAISE EXCEPTION 'multiplix_dispatch_not_found' USING ERRCODE = 'P0002';
59:   END IF;
60: 
61:   CASE p_action
62:     WHEN 'start' THEN
63:       IF v_dispatch.status = 'sending' AND v_dispatch.updated_at > now() - interval '3 minutes' THEN
64:         RAISE EXCEPTION 'multiplix_dispatch_already_running' USING ERRCODE = '55001';
65:       END IF;
66:       IF v_dispatch.status NOT IN ('draft', 'scheduled', 'paused', 'sending') THEN
67:         RAISE EXCEPTION 'multiplix_dispatch_start_denied_from_%', v_dispatch.status USING ERRCODE = '55000';
68:       END IF;
69:       IF btrim(COALESCE(v_dispatch.message_template, '')) = '' THEN
70:         RAISE EXCEPTION 'multiplix_dispatch_message_required' USING ERRCODE = '22023';
71:       END IF;
72:       IF v_dispatch.total_recipients <= 0
73:          OR NOT EXISTS (
74:            SELECT 1 FROM public.multiplix_recipients AS recipient
75:            WHERE recipient.dispatch_id = p_dispatch_id
76:          ) THEN
77:         RAISE EXCEPTION 'multiplix_dispatch_recipients_required' USING ERRCODE = '22023';
78:       END IF;
79:       v_next_status := 'sending';
80:     WHEN 'pause' THEN
81:       IF v_dispatch.status <> 'sending' THEN
82:         RAISE EXCEPTION 'multiplix_dispatch_pause_denied_from_%', v_dispatch.status USING ERRCODE = '55000';
83:       END IF;
84:       v_next_status := 'paused';
85:     WHEN 'cancel' THEN
86:       IF v_dispatch.status NOT IN ('draft', 'scheduled', 'sending', 'paused') THEN
87:         RAISE EXCEPTION 'multiplix_dispatch_cancel_denied_from_%', v_dispatch.status USING ERRCODE = '55000';
88:       END IF;
89:       v_next_status := 'cancelled';
90:   END CASE;
91: 
92:   -- F14: cancelar tem de encerrar a fila. Item sem POST ao provedor vira
93:   -- 'cancelled' (com motivo explicito); item em voo (provider_dispatch_started_at
94:   -- preenchido) fica intacto — o resultado dele ainda e desconhecido e o sweeper
95:   -- (abaixo) resolve para outcome_unknown.
96:   IF p_action = 'cancel' THEN
97:     UPDATE public.multiplix_recipients AS recipient
98:        SET status = 'cancelled',
99:            error_message = COALESCE(recipient.error_message, 'Cancelado pelo operador antes do envio'),
100:            delivery_claim_token = NULL,
101:            delivery_claimed_at = NULL,
102:            delivery_claim_expires_at = NULL,
103:            delivery_claimed_by = NULL,
104:            retry_after = NULL,
105:            updated_at = statement_timestamp()
106:      WHERE recipient.dispatch_id = p_dispatch_id
107:        AND recipient.status IN ('pending', 'sending')
108:        AND recipient.provider_dispatch_started_at IS NULL;
109: 
110:     GET DIAGNOSTICS v_closed = ROW_COUNT;
111: 
112:     -- F57 (achado): o comentario acima fala de ITEM, mas ate agora so a fila ANTIGA
113:     -- (multiplix_recipients) era encerrada. Com o worker por item (F55) isso deixa
114:     -- item pending na fila — e ele seria enviado DEPOIS de o operador cancelar, ou
115:     -- seja, mensagem indesejada para cliente real. Mesma regra: item sem POST ao
116:     -- provedor vira 'cancelled'; item JA enviado (provider_dispatch_started_at
117:     -- preenchido) fica intacto, porque o resultado dele ainda e desconhecido e quem
118:     -- resolve e o sweeper, nao um cancel cego.
119:     UPDATE public.multiplix_delivery_items AS item
120:        SET status = 'cancelled',
121:            error_message = COALESCE(item.error_message, 'Cancelado pelo operador antes do envio'),
122:            lease_token = NULL,
123:            lease_until = NULL,
124:            worker_id = NULL,
125:            updated_at = statement_timestamp()
126:      WHERE item.dispatch_id = p_dispatch_id
127:        AND item.status IN ('pending', 'sending')
128:        AND item.provider_dispatch_started_at IS NULL;
129:   END IF;
130: 
131:   UPDATE public.multiplix_dispatches AS dispatch
132:   SET status       = v_next_status::public.multiplix_dispatch_status,
133:       pause_reason = CASE WHEN p_action = 'pause' THEN p_pause_reason ELSE NULL END,
134:       started_at   = CASE WHEN p_action = 'start'
135:         THEN COALESCE(dispatch.started_at, statement_timestamp())
136:         ELSE dispatch.started_at END,
137:       paused_at    = CASE WHEN p_action = 'pause' THEN statement_timestamp() ELSE dispatch.paused_at END,
138:       completed_at = CASE WHEN p_action = 'cancel' THEN statement_timestamp() ELSE dispatch.completed_at END,
139:       updated_at   = statement_timestamp()
140:   WHERE dispatch.id = p_dispatch_id;
141: 
142:   RETURN QUERY SELECT p_dispatch_id, v_dispatch.status::text, v_next_status::text;
143: END;
144: $function$;

